	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 1)
	assertPick(t, selectSession(t, r, "svc", 1, "x"), "a", "h1:1", 1)

	assertABCHealthy(t, r)
}

// releaseRaw validates and applies a release_session request, returning the
// outcome directly so conflict cases can be asserted instead of fatally
// failing. It mirrors releaseSession but does not require success.
func releaseRaw(t *testing.T, r *Registry, service string, revision int64, key string) ReleaseOutcome {
	t.Helper()
	rel, err := r.ValidateSessionRelease(service, revision, &key)
	if err != nil {
		t.Fatalf("validate release %s key %q: %v", service, key, err)
	}
	return r.ReleaseSession(rel)
}

